const actions={
close:()=>close(),switch:()=>open('switch'),actor:p=>{if(!actors.includes(p))return;user=p;localStorage.setItem('nido-actor-v3',user);filter='all';docQuery='';docType='';docFrom='';docTo='';medQuery='';medView='all';simpleAgenda=true;chat=[];tab='calendar';selected=today();close();render();toast(`Ahora estás viendo como ${people[p].name}`)},
tab:t=>{tab=t;filter='all';docQuery='';close();render()},filter:p=>{filter=p;render()},'cal-section':v=>{calSection=v;render()},'cal-mode':()=>{calMode=calMode==='week'?'month':'week';render()},day:d=>{selected=d;render()},today:()=>{selected=today();render()},shift:n=>{if(calMode==='week')selected=addDay(selected,Number(n)*7);else{const d=new Date(selected+'T12:00');d.setDate(1);d.setMonth(d.getMonth()+Number(n));selected=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-01`}render()},
'new-event':()=>allowedPatients('agenda').length?open('event-form'):toast('No tenés un integrante disponible para crear actividades.'),'edit-event':id=>open('event-form',id),event:id=>open('event',id),
complete:id=>{let e=db.events.find(e=>e.id===id);if(!accessibleEvent(e))return denied();e.status='done';log(e,'Marcó como realizada');render();toast('Actividad registrada')},reopen:id=>{let e=db.events.find(e=>e.id===id);if(!accessibleEvent(e))return denied();e.status='pending';e.response=null;e.reassignment=null;log(e,'Reabrió el pendiente');render()},'confirm-cancel':id=>open('cancel',id),'cancel-event':id=>{let e=db.events.find(e=>e.id===id);if(!accessibleEvent(e))return denied();e.status='canceled';log(e,'Canceló la actividad');saved('Actividad cancelada; se conserva su registro')},question:id=>open('question',id),
document:id=>open('document',id),upload:()=>open('upload'),example:()=>{const owner=$('#upload-form select')?.value||allowedPatients()[0];open('review','',{owner,example:true})},'finish-upload':()=>{tab='docs';filter='all';saved('Documento guardado')},'doc-task':id=>open('doc-task',id),'doc-privacy':id=>open('privacy',id),
'new-med':()=>open('med-form'),med:id=>open('med',id),batch:arg=>{const [id,batch]=arg.split(':');open('batch',id,{batch})},purchase:id=>open('purchase',id),shopping:id=>{let m=db.meds.find(m=>m.id===id);if(!can(m))return denied();m.shopping=!m.shopping;log(m,m.shopping?'Agregó a reposición':'Quitó de reposición');render()},renew:id=>{let m=db.meds.find(m=>m.id===id);if(!can(m))return denied();if(!db.events.some(e=>e.medSource===id&&e.status==='pending'))db.events.push({id:window.crypto.randomUUID(),owner:m.owner,medSource:id,title:`Renovar receta de ${m.title}`,date:'',time:'',type:'Trámite',assignee:user,visibility:m.visibility,status:'pending',notes:'Coordinar la renovación con el prestador.',history:[]});tab='calendar';calSection='tasks';saved('Gestión de receta agregada a pendientes')},
person:id=>open('person',id),'person-docs':p=>{tab='docs';filter=p;close();render()},notes:p=>open('notes',p),vaccines:p=>open('vaccines',p),permissions:p=>open('permissions',p),
revoke:who=>{if(sheetState?.id!==user)return;delete db.grants[user][who];db.audit.push({owner:user,by:user,at:stamp(),action:`Revocó el acceso de ${people[who].name}`});persist();render();toast('Acceso revocado')},grant:who=>{if(sheetState?.id!==user)return;db.grants[user][who]=who==='rosa'?'care':'manage';db.audit.push({owner:user,by:user,at:stamp(),action:`Autorizó a ${people[who].name}`});db.requests.filter(r=>r.owner===user&&r.by===who).forEach(r=>r.status='accepted');persist();render()},request:owner=>{if(user!=='sofia'||db.requests.some(r=>r.owner===owner&&r.status==='pending'))return toast('La solicitud está pendiente');db.requests.push({id:id(),owner,by:user,status:'pending'});persist();render();toast('Solicitud registrada. Antonio puede aceptarla en su perfil.')},approve:rid=>{const r=db.requests.find(r=>r.id===rid);if(r?.owner!==user)return;actions.grant(r.by)},alerts:()=>open('alerts'),ask:q=>ask(q),reset:()=>open('reset'),'confirm-reset':()=>{db=seed();user='sofia';localStorage.setItem('nido-actor-v3',user);chat=[];tab='calendar';filter='all';saved('Datos de ejemplo restablecidos')}
};
// Boxes, expiry dates and prescription workflow. These are user-entered records, not clinical rules.
function batchState(b){
 if(b.archived)return {label:'Retirada del inventario',tone:'',key:'archived'};
 if(b.qty===0)return {label:'Sin unidades',tone:'',key:'empty'};
 if(!b.expiry)return {label:'Vencimiento sin registrar',tone:'warn',key:'unknown'};
 const days=daysTo(b.expiry);
 if(days<0)return {label:'Fecha vencida',tone:'danger',key:'expired'};
 if(days===0)return {label:'Vence hoy',tone:'warn',key:'soon'};
 if(days<=30)return {label:`Vence en ${days} días`,tone:'warn',key:'soon'};
 return {label:'Fecha registrada vigente',tone:'',key:'current'};
}
function stockTotals(m){return m.batches.filter(b=>!b.archived).reduce((t,b)=>{t.total+=b.qty;if(!b.expiry)t.unknown+=b.qty;else if(daysTo(b.expiry)<0)t.expired+=b.qty;else t.dated+=b.qty;return t},{total:0,dated:0,expired:0,unknown:0})}
function prescriptionState(m){
 if(m.rxMode==='none')return {key:'none',tone:'',label:'No aplica, según registro'};
 if(!m.rx)return {key:'unknown',tone:'warn',label:'Vencimiento sin registrar'};
 const d=daysTo(m.rx);
 if(d<0)return {key:'expired',tone:'danger',label:'Fecha de receta vencida'};
 if(d<=Number(m.rxLead??15))return {key:'soon',tone:'warn',label:d===0?'Receta vence hoy':`Receta vence en ${d} días`};
 return {key:'current',tone:'',label:`Receta hasta ${dateLabel(m.rx)}`};
}
function needsAttention(m){return stockTotals(m).dated<=Number(m.lowAt??7)||m.batches.some(b=>!b.archived&&b.qty>0&&batchState(b).key!=='current')||['unknown','expired','soon'].includes(prescriptionState(m).key)}
function renewalEvent(m){return db.events.find(e=>e.medSource===m.id&&e.status==='pending')}
function renewalState(m){const e=renewalEvent(m);if(e)return e.renewalStage||'requested';return m.renewal?.status||'none'}
const renewalLabels={none:'Sin gestión iniciada',requested:'Renovación pendiente',appointment:'Consulta coordinada',received:'Nueva receta registrada'};
function medicineCard(m){const st=stockTotals(m),rx=prescriptionState(m);return `<button class="card action" data-action="med" data-id="${m.id}"><div class="between"><div><small>${people[m.owner].name}</small><h3 style="margin-top:5px">${esc(m.title)}</h3></div><span class="avatar" style="${personStyle(m.owner)}">${icon('meds')}</span></div><div class="stock-numbers"><div><span class="quantity">${st.total}</span><small>${esc(m.unit)} en inventario</small></div><div><strong>${m.batches.filter(b=>!b.archived).length}</strong><small>cajas registradas</small></div></div><div class="meta">${st.expired?`<span class="tag danger">${st.expired} con fecha vencida</span>`:''}${st.unknown?`<span class="tag warn">${st.unknown} sin fecha</span>`:''}${m.batches.some(b=>!b.archived&&batchState(b).key==='soon')?'<span class="tag warn">Caja próxima a vencer</span>':''}<span class="tag ${rx.tone}">${rx.label}</span>${m.shopping?'<span class="tag warn">En reposición</span>':''}</div><p>${renewalLabels[renewalState(m)]}</p></button>`}
function medicineDashboard(){
 const all=filtered(db.meds);let list=all.filter(m=>(m.title+' '+people[m.owner].name).toLowerCase().includes(medQuery.toLowerCase()));
 if(medView==='attention')list=list.filter(needsAttention);
 if(medView==='recipes')list=list.filter(m=>m.rxMode!=='none');
 if(medView==='shopping')list=list.filter(m=>m.shopping);
 return `<div class="page-title between"><div><h1>Medicamentos</h1><p>Cajas, vencimientos y recetas.</p></div>${allowedPatients('meds').length?button(icon('plus'),'new-med','','iconbtn'):''}</div>${chips('meds')}<form id="med-search-form" class="search">${icon('search')}<input name="query" type="search" aria-label="Buscar medicamentos" placeholder="Nombre del medicamento" value="${esc(medQuery)}"></form><div class="med-filters">${[['all','Todos'],['attention','Revisar'],['recipes','Recetas'],['shopping','Reposición']].map(([k,t])=>button(t,'med-view',k,`chip ${medView===k?'active':''}`)).join('')}</div>${all.length?`<div class="summary"><h3>${all.filter(needsAttention).length} para revisar · ${all.filter(m=>m.shopping).length} en reposición</h3><p>Las fechas de cajas y recetas se controlan por separado.</p></div>`:''}${list.map(medicineCard).join('')||empty('Sin resultados','No hay medicamentos disponibles con estos filtros.')}`;
}
function medicineDetail(m){
 const st=stockTotals(m),rx=prescriptionState(m);const ordered=m.batches.filter(b=>!b.archived).slice().sort((a,b)=>(a.expiry||'9999').localeCompare(b.expiry||'9999'));const first=ordered.find(b=>b.qty>0&&b.expiry&&daysTo(b.expiry)>=0);
 sheet('Medicamento',`<small>${people[m.owner].name}</small><h2 style="margin:7px 0 18px">${esc(m.title)}</h2><div class="stock-numbers"><div><span class="quantity">${st.total}</span><small>${esc(m.unit)} registrados</small></div><div><strong>${st.dated}</strong><small>con fecha vigente</small></div></div>${st.expired||st.unknown?`<div class="notice">${st.expired} con fecha vencida · ${st.unknown} sin fecha registrada. Estas cantidades se muestran separadas.</div>`:''}<p class="muted tiny">Última actualización: ${dateLabel(m.updated)}</p><div class="section-title">Cajas, por fecha de vencimiento</div>${ordered.map(b=>{const index=m.batches.indexOf(b)+1,status=batchState(b);return `<div class="card"><div class="between"><h3>Caja ${index}</h3><span class="tag ${status.tone}">${status.label}</span></div><p><strong>${b.qty} ${esc(m.unit)}</strong> · Vence ${dateLabel(b.expiry)}</p>${first?.id===b.id?'<p class="tiny">Primera fecha vigente registrada.</p>':''}<div class="actions">${button('Corregir','batch',m.id+':'+b.id,'btn quiet tiny')}${button('Retirar caja','retire-box',m.id+':'+b.id,'btn quiet tiny')}</div></div>`}).join('')||empty('Sin cajas activas','Podés agregar una caja al registrar una compra.')}${m.batches.some(b=>b.archived)?`<details class="card"><summary>Cajas retiradas (${m.batches.filter(b=>b.archived).length})</summary>${m.batches.filter(b=>b.archived).map(b=>`<p>Caja ${m.batches.indexOf(b)+1} · ${b.qty} ${esc(m.unit)} · ${esc(b.archiveReason)}</p>${button('Restaurar caja','restore-box',m.id+':'+b.id,'btn quiet tiny')}`).join('')}</details>`:''}<div class="actions">${button('Registrar compra / caja','purchase',m.id)}${button(m.shopping?'Quitar de reposición':'Agregar a reposición','shopping',m.id,'btn secondary')}</div><div class="section-title">Receta</div><div class="card"><div class="meta"><span class="tag ${rx.tone}">${rx.label}</span><span class="tag">${renewalLabels[renewalState(m)]}</span></div><p>Fecha de vencimiento: ${dateLabel(m.rx)}</p><p>Aviso configurado: ${m.rxLead??15} días antes.</p>${renewalEvent(m)?`<p>Responsable: ${people[renewalEvent(m).assignee]?.name||'Sin asignar'} · ${dateLabel(renewalEvent(m).date)}</p>`:''}<div class="actions">${button('Gestionar renovación','renew',m.id,'btn secondary')}${button('Registrar nueva receta','rx-received',m.id,'btn quiet')}</div></div>${button('Editar datos y avisos','med-settings',m.id,'btn quiet full')}${history(m.history)}<div class="notice demo">Las fechas y cantidades son ingresadas por la familia. No se validan recetas ni se envían pedidos a terceros.</div>`);
}
function simpleCalendar(){
 const all=visible(db.events).filter(e=>e.status!=='canceled');const dated=all.filter(e=>e.date===selected).sort((a,b)=>a.time.localeCompare(b.time));const next=all.filter(e=>e.date>selected&&e.status==='pending').sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)).slice(0,2);
 return `<section class="simple-agenda"><div class="page-title"><small>Tu agenda personal</small><h1>Hola, Antonio</h1><p>${selected===today()?'Esto tenés para hoy.':dateLabel(selected)}</p></div><div class="simple-days">${button('Hoy','simple-day',today(),selected===today()?'btn':'btn quiet')}${button('Mañana','simple-day',addDay(today(),1),selected===addDay(today(),1)?'btn':'btn quiet')}</div><div class="section-title">${dateLabel(selected)}</div>${dated.length?dated.map(eventCard).join(''):empty('Sin actividades para este día','Tus próximas actividades aparecen más abajo.')}<div class="section-title">Lo próximo</div>${next.map(eventCard).join('')||'<p class="muted">No hay otras actividades con fecha.</p>'}<div class="actions">${button(icon('meds')+' Mis medicamentos','tab','meds','btn secondary full')}${button('Ver todos mis pendientes','simple-pending','','btn quiet full')}</div>${button('Abrir calendario completo','full-calendar','','muted-button')}</section>`;
}
function permissionOverview(owner){
 const grants=db.grants[owner]||{};sheet('Acceso por categoría',`<p>Elegí qué puede ver y gestionar cada persona. «Solo yo» siempre queda privado.</p>${Object.entries(grants).map(([who,g])=>`<div class="card"><div class="row">${avatar(who)}<div><h3>${people[who].name}</h3><p>${grantCategories(g).map(k=>categories[k]).join(' · ')}</p></div></div><div class="actions">${button('Elegir categorías','edit-categories',who,'btn secondary')}${button('Revocar todo','revoke',who,'btn quiet')}</div></div>`).join('')||empty('Sin accesos activos','Tu información solo está disponible para vos.')}${actors.filter(p=>p!==owner&&!grants[p]).map(p=>button(`Compartir con ${people[p].name}`,'grant',p,'btn secondary full')).join('')}${db.requests.filter(r=>r.owner===owner&&r.status==='pending').map(r=>`<div class="card"><h3>${people[r.by].name} solicita acceso</h3>${button('Revisar solicitud','approve',r.id,'btn full')}</div>`).join('')}${history(db.audit.filter(a=>a.owner===owner))}`);
}
function extraSheet(s){
 let m=db.meds.find(m=>m.id===s.id);
 if(['renewal','rx-received','med-settings','retire'].includes(s.type)&&!can(m)){denied();return true}
 if(s.type==='renewal'){
  const e=renewalEvent(m);sheet('Renovación de receta',`<h3>${esc(m.title)}</h3><p class="muted tiny">${people[m.owner].name} · ${renewalLabels[renewalState(m)]}</p><form id="renewal-form"><label>Estado de la gestión</label><select name="status"><option value="requested" ${e?.renewalStage!=='appointment'?'selected':''}>Pendiente de coordinar</option><option value="appointment" ${e?.renewalStage==='appointment'?'selected':''}>Consulta ya coordinada</option></select><label>Responsable</label><select name="assignee">${actors.filter(p=>p===user||grantCategories(db.grants[m.owner]?.[p]).includes('meds')||p===m.owner).map(p=>`<option value="${p}" ${e?.assignee===p?'selected':''}>${people[p].name}</option>`).join('')}</select><label>Fecha para gestionar / consulta</label><input type="date" name="date" value="${e?.date||''}"><label>Notas</label><textarea name="notes">${esc(e?.notes||'Coordinar la renovación con el prestador.')}</textarea><button class="btn full" style="margin-top:18px">Guardar gestión</button></form><div class="notice">Se crea un único pendiente vinculado. Guardar la gestión no cambia el vencimiento de la receta.</div>`);return true;
 }
 if(s.type==='rx-received'){sheet('Registrar nueva receta',`<h3>${esc(m.title)}</h3><form id="rx-received-form"><label>Fecha de vencimiento indicada en la receta</label><input type="date" name="expiry"><label class="check"><input type="checkbox" name="unknown">La receta no tiene una fecha confirmada</label><label>Referencia o nota (opcional)</label><input name="reference" placeholder="Ej. emitida en consulta del 12/11"><label class="check"><input type="checkbox" name="confirmed" required>Revisé la receta y confirmo estos datos</label><button class="btn full" style="margin-top:18px">Guardar nueva receta</button></form><div class="notice">Se conserva el vencimiento anterior en el historial. La gestión de renovación se marcará resuelta.</div>`);return true}
 if(s.type==='med-settings'){sheet('Datos y avisos',`<form id="med-settings-form"><label>Nombre y presentación</label><input name="title" value="${esc(m.title)}" required><label>Revisar cantidad cuando haya hasta</label><input name="lowAt" type="number" min="0" step="1" value="${m.lowAt??7}" required><p class="muted tiny">${esc(m.unit)} con fecha registrada vigente. No calcula días de tratamiento.</p><label>Receta</label><select name="rxMode"><option value="registered" ${m.rxMode!=='none'?'selected':''}>Registrar o revisar su vigencia</option><option value="none" ${m.rxMode==='none'?'selected':''}>No aplica, según mi registro</option></select><label>Vencimiento actual (opcional)</label><input type="date" name="rx" value="${m.rx||''}"><label>Avisar cuántos días antes</label><input type="number" name="rxLead" min="0" max="365" step="1" value="${m.rxLead??15}" required><button class="btn full" style="margin-top:18px">Guardar cambios</button></form>`);return true}
 if(s.type==='retire'){const b=m.batches.find(b=>b.id===s.batch);if(!b){denied();return true}sheet('Retirar caja del inventario',`<h3>${esc(m.title)} · Caja ${m.batches.indexOf(b)+1}</h3><p>${b.qty} ${esc(m.unit)} dejarán de contar en el inventario activo. Podés restaurar el registro.</p><form id="retire-form"><label>Motivo</label><select name="reason"><option>Fecha vencida</option><option>Caja agotada</option><option>Ya no está en casa</option><option>Registro duplicado</option></select><button class="btn danger full" style="margin-top:18px">Retirar del inventario</button></form>`);return true}
 if(s.type==='categories'){
  if(s.owner!==user){denied();return true}
  const cats=grantCategories(db.grants[user]?.[s.who]);const selected=cats.length?cats:s.who==='rosa'?['care']:Object.keys(categories);
  sheet(`Compartir con ${people[s.who].name}`,`<form id="categories-form"><p>Esta persona podrá ver y gestionar solo las categorías elegidas.</p>${Object.entries(categories).map(([k,label])=>`<label class="check permission-option"><input type="checkbox" name="categories" value="${k}" ${selected.includes(k)?'checked':''}><span>${label}</span></label>`).join('')}<div class="notice">Los documentos «Solo yo» nunca se incluyen. Una actividad vinculada a un documento también requiere permiso para ese documento.</div><button class="btn full">Guardar permisos</button></form>`);return true;
 }
 if(s.type==='feedback'){
  sheet('Contanos cómo te fue',`<p>Explorá a tu ritmo. Cuando termines, contanos qué te resultó claro y qué mejorarías.</p><form id="feedback-form"><label>¿Qué tan fácil te resultó?</label><select name="ease" required><option value="">Elegir</option><option>Muy fácil</option><option>Bastante fácil</option><option>Ni fácil ni difícil</option><option>Difícil</option></select><label>¿Qué intentaste hacer?</label><textarea name="tried" required></textarea><label>¿Dónde te trabaste o qué cambiarías?</label><textarea name="improve"></textarea><button class="btn full">Guardar comentario en este celular</button></form>${db.feedback?.some(f=>f.by===user)?button('Descargar mis comentarios','export-feedback','','btn quiet full'):''}<div class="notice demo">Se guarda solo en este navegador. Descargá el archivo si querés compartirlo con el equipo.</div>`);return true;
 }
 return false;
}
function handleExtraForm(form,f,v,s){
 if(form.id==='med-search-form'){medQuery=v.query.trim();render();return true}
 if(form.id==='categories-form'){
  if(s.owner!==user){denied();return true}
  const cats=f.getAll('categories').filter(k=>Object.hasOwn(categories,k));
  if(cats.length)db.grants[user][s.who]={categories:cats};else delete db.grants[user][s.who];
  db.requests.filter(r=>r.owner===user&&r.by===s.who&&r.status==='pending').forEach(r=>r.status=cats.length?'accepted':'declined');
  db.audit.push({owner:user,by:user,at:stamp(),action:`Permisos de ${people[s.who].name}: ${cats.map(k=>categories[k]).join(', ')||'ninguno'}`});persist();open('permissions',user);render();toast('Permisos actualizados');return true;
 }
 if(['renewal-form','rx-received-form','med-settings-form','retire-form'].includes(form.id)){
  const m=db.meds.find(m=>m.id===s.id);if(!can(m)){denied();return true}
  if(form.id==='renewal-form'){
   if(v.status==='appointment'&&!v.date){toast('Indicá la fecha de la consulta coordinada.');return true}
   let e=renewalEvent(m);
   if(!e){e={id:id(),owner:m.owner,medSource:m.id,title:`Renovar receta de ${m.title}`,type:'Trámite',time:'',status:'pending',visibility:m.visibility,history:[]};db.events.push(e)}
   Object.assign(e,{renewalStage:v.status,assignee:v.assignee,date:v.date,notes:v.notes.trim()});
   m.renewal={status:v.status,eventId:e.id};log(e,'Actualizó gestión de renovación');log(m,`Renovación: ${renewalLabels[v.status]}`);
  }
  if(form.id==='rx-received-form'){
   if(!v.confirmed){toast('Confirmá la revisión de los datos.');return true}
   if(!v.expiry&&!v.unknown){toast('Ingresá el vencimiento o indicá que la fecha no está confirmada.');return true}
   if(v.expiry&&v.unknown){toast('Elegí una fecha o marcala como no confirmada, no ambas.');return true}
   const before=m.rx;m.rx=v.unknown?'':v.expiry;m.rxMode='registered';m.renewal={status:'received',at:stamp(),reference:v.reference.trim()};
   db.events.filter(e=>e.medSource===m.id&&e.status==='pending').forEach(e=>{e.status='done';e.renewalStage='received';log(e,'Registró nueva receta y cerró la gestión')});
   log(m,`Nueva receta: ${dateLabel(before)} → ${dateLabel(m.rx)}${v.reference.trim()?' · '+v.reference.trim():''}`);
  }
  if(form.id==='med-settings-form'){
   if(!v.title.trim()){toast('Ingresá el nombre.');return true}
   const before=m.rx;Object.assign(m,{title:v.title.trim(),lowAt:Number(v.lowAt),rxLead:Number(v.rxLead),rxMode:v.rxMode,rx:v.rxMode==='none'?'':v.rx});
   log(m,`Editó datos y avisos. Receta: ${dateLabel(before)} → ${dateLabel(m.rx)}`);
  }
  if(form.id==='retire-form'){
   const b=m.batches.find(b=>b.id===s.batch);if(!b){denied();return true}b.archived=true;b.archiveReason=v.reason;m.updated=today();log(m,`Retiró caja ${m.batches.indexOf(b)+1}: ${v.reason} (${b.qty} ${m.unit})`);
  }
  persist();open('med',m.id);render();toast('Cambios guardados');return true;
 }
 if(form.id==='feedback-form'){
  db.feedback??=[];db.feedback.push({id:id(),by:user,at:stamp(),ease:v.ease,tried:v.tried.trim(),improve:v.improve.trim()});persist();render();toast('Comentario guardado en este navegador');return true;
 }
 return false;
}
const extraActions={
 'person-meds':p=>{tab='meds';filter=p;close();render()},'med-view':view=>{medView=view;render()},
 renew:mid=>open('renewal',mid),'rx-received':mid=>open('rx-received',mid),'med-settings':mid=>open('med-settings',mid),
 'retire-box':arg=>{const [mid,batch]=arg.split(':');open('retire',mid,{batch})},
 'restore-box':arg=>{const [mid,bid]=arg.split(':'),m=db.meds.find(m=>m.id===mid);if(!can(m))return denied();const b=m.batches.find(b=>b.id===bid);if(!b)return;b.archived=false;m.updated=today();log(m,`Restauró caja ${m.batches.indexOf(b)+1}`);render()},
 'simple-home':()=>{simpleAgenda=true;selected=today();render()},'simple-day':d=>{selected=d;render()},'full-calendar':()=>{simpleAgenda=false;render()},'simple-pending':()=>{simpleAgenda=false;calSection='tasks';render()},
 'edit-categories':who=>{if(sheetState?.id!==user)return;open('categories','',{owner:user,who})},
 grant:who=>{if(sheetState?.id!==user)return;open('categories','',{owner:user,who})},
 approve:rid=>{const r=db.requests.find(r=>r.id===rid);if(r?.owner!==user)return;open('categories','',{owner:user,who:r.by})},
 feedback:()=>open('feedback'),
 'export-feedback':()=>{const comments=(db.feedback||[]).filter(f=>f.by===user);const blob=new Blob([JSON.stringify(comments,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='comentarios-nido.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
};

// Extra workflows are registered before interaction starts.
Object.assign(actions,extraActions,discoveryActions,followupActions,analysisActions);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){const action=actions[b.dataset.action];if(action)action(b.dataset.id)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,f=new FormData(form),v=Object.fromEntries(f.entries()),s=sheetState;
if(analysisForm(form,f,v,s))return;
if(followupForm(form,f,v,s))return;
if(await handleDiscoveryForm(form,f,v,s))return;
if(handleExtraForm(form,f,v,s))return;
if(form.id==='search-form'){docQuery=v.query;return render()}
if(form.id==='chat-form'){if(v.query.trim())ask(v.query.trim());return}
if(form.id==='event-form'){let prior=s.id?db.events.find(e=>e.id===s.id):null;if(prior&&!can(prior,'care')||!canOwner(v.owner,(user==='rosa'||v.type==='Cuidado')?'care':'calendar'))return denied();if(!v.title.trim())return;const r={...(prior||{id:id(),status:'pending',history:[]}),owner:prior?.source?prior.owner:v.owner,title:v.title.trim(),date:v.date,time:v.time,type:v.type,scope:user==='rosa'?'care':v.type==='Cuidado'?'care':'calendar',assignee:v.assignee,location:v.location,notes:v.notes,reminder:v.reminder,recipient:v.recipient,visibility:v.owner===user&&v.private?'private':prior?.visibility==='private'&&prior.owner!==user?'private':'shared'};if(prior&&(prior.date!==r.date||prior.time!==r.time||prior.assignee!==r.assignee)){r.response=null;r.simulatedRepeats=0;if(prior.assignee!==r.assignee)r.reassignment=null}if(r.tracking?.stage==='to_book'){if(r.tracking.targetDate&&r.date>r.tracking.targetDate){toast('El inicio de gestión debe ser anterior o igual al objetivo.');return}r.tracking={...r.tracking,planDate:r.date}}if(prior)db.events[db.events.indexOf(prior)]=r;else db.events.push(r);log(r,prior?'Editó la actividad':'Creó la actividad');selected=r.date||today();saved('Actividad guardada');return}
if(form.id==='upload-form'){const file=f.get('file'),by=user,owner=v.owner;if(!canOwner(owner))return denied();if(!file||!file.size)return toast('Elegí un archivo o usá el ejemplo preparado.');if(file.size>1024*1024)return toast('El archivo supera 1 MB. Usá uno más pequeño para la demo.');if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type))return toast('Elegí una imagen JPG, PNG, WebP o un PDF.');const submit=form.querySelector('button');submit.disabled=true;try{const attachment=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('No se pudo leer el archivo.'));reader.readAsDataURL(file)});if(user!==by||sheetState!==s||!canOwner(owner))return toast('La vista cambió. Volvé a elegir el archivo.');const r={id:id(),owner,title:file.name||'Documento sin título',date:'',text:'',kind:'Documento',visibility:v.private?'private':'shared',by,attachment,filename:file.name,needsDetails:true};db.documents.push(r);if(!persist()){db.documents.pop();return}open('doc-saved',r.id)}catch(err){toast(err.message)}finally{submit.disabled=false}return}
if(form.id==='review-form'){if(!canOwner(v.owner))return denied();const r={id:id(),owner:v.owner,title:v.title.trim(),date:v.date,text:v.text.trim(),kind:v.kind||'Documento',visibility:v.private?'private':'shared',by:user,attachment:s.attachment||null,filename:s.filename||null};db.documents.push(r);if(!persist()){db.documents.pop();return}open('doc-saved',r.id);return}
if(form.id==='doc-task-form'){const d=db.documents.find(d=>d.id===s.id);if(!can(d)||!canOwner(d.owner,'calendar'))return denied();const planned=v.date||(v.targetDate?addDay(v.targetDate,-Number(v.leadDays)):'' );if(v.targetDate&&planned>v.targetDate){toast('El inicio de gestión debe ser anterior o igual al objetivo.');return}db.events.push({id:id(),owner:d.owner,title:v.title.trim(),date:planned,time:'',type:'Pendiente',assignee:v.assignee,recipient:v.assignee,reminder:planned?'Al comenzar la gestión':'Sin recordatorio',tracking:{stage:'to_book',targetDate:v.targetDate,planDate:planned},source:d.id,visibility:d.visibility,status:'pending',notes:'Creado a partir de un documento. Revisar la fuente antes de gestionar.',history:[{by:user,at:stamp(),action:'Creó pendiente desde documento'}]});tab='calendar';calSection='tasks';saved('Pendiente creado y vinculado a su fuente');return}
if(form.id==='med-form'){if(!canOwner(v.owner,'meds'))return denied();db.meds.push({id:id(),owner:v.owner,title:v.title.trim(),unit:v.unit,rx:v.rx,visibility:'shared',updated:today(),shopping:false,batches:[{id:id(),qty:Number(v.qty),expiry:v.expiry}],history:[{by:user,at:stamp(),action:'Registró medicamento'}]});saved('Medicamento registrado');return}
if(form.id==='stock-form'){const m=db.meds.find(m=>m.id===s.id);if(!can(m))return denied();const n=Number(v.qty);if(!Number.isInteger(n)||n<0)return toast('Ingresá una cantidad válida.');if(s.type==='purchase'){m.batches.push({id:id(),qty:n,expiry:v.expiry});m.shopping=false}else{const b=m.batches.find(b=>b.id===s.batch);const oldQty=b.qty;const oldExpiry=b.expiry;b.qty=n;b.expiry=v.expiry;m.history??=[];m.history.push({by:user,at:stamp(),action:`Caja: ${oldQty} → ${n}; vencimiento ${dateLabel(oldExpiry)} → ${dateLabel(v.expiry)}`})}m.updated=today();log(m,s.type==='purchase'?'Registró compra':'Corrigió existencias');open('med',m.id);render();return}
if(form.id==='privacy-form'){const d=db.documents.find(d=>d.id===s.id);if(d?.owner!==user)return denied();d.visibility=v.visibility;db.events.filter(e=>e.source===d.id).forEach(e=>e.visibility=v.visibility);db.audit.push({owner:user,by:user,at:stamp(),action:`Cambió visibilidad de ${d.title} a ${v.visibility==='private'?'Solo yo':'Compartido'}`});persist();open('document',d.id);render();return}
if(form.id==='note-form'){if(!canOwner(s.id,'care'))return denied();db.notes.push({id:id(),owner:s.id,by:user,scope:'care',visibility:'shared',date:today(),text:v.text.trim()});persist();render();toast('Observación guardada');return}
if(form.id==='vaccine-form'){if(!canOwner(s.id,'vaccines'))return denied();db.vaccines.push({id:id(),owner:s.id,title:v.title.trim(),date:v.date,visibility:'shared',text:'Registro ingresado manualmente en la demo.'});persist();render();return}
if(form.id==='question-form'){const r=db.events.find(e=>e.id===s.id);if(!can(r,'care'))return denied();r.questions??=[];r.questions.push(v.text.trim());log(r,'Agregó pregunta para la consulta');open('event',r.id);render();return}
});
render();
if(!localStorage.getItem('nido-actor-v3'))open('switch');
